class ScriptContextRuntimeContracts {
 const BindingFlags F=BindingFlags.Static|BindingFlags.NonPublic;static int checks;
 static object Get(string name){return typeof(CW3Runtime).GetField(name,F).GetValue(null);}static void Set(string name,object value){typeof(CW3Runtime).GetField(name,F).SetValue(null,value);}static void Need(bool v,string label){checks++;if(!v)throw new Exception(label);}
 static string Hash(string code){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(code))).Replace("-","").ToLowerInvariant();}
 static void Main(){Set("loaded",true);var definitions=(Dictionary<string,Hashtable>)Get("definitions");var translations=(Dictionary<string,string>)Get("translations");var bindings=(ScriptBindings)Get("scriptBindings");var cores=new List<Core>();
  for(int n=0;n<4;n++){string name="Script"+n,code="owned script "+n;GameSpace.instance.scriptManager.Scripts[name]=code;var d=new Hashtable{{"id",name},{"kind","crpl_output"},{"script",name},{"script_hash",Hash(code)},{"call_line",12},{"call_index",1},{"source","Value: {0}"},{"slots",new ArrayList{"number"}}};definitions.Add(name,d);translations.Add(name,"值：{0}");bindings.Add(d);cores.Add(new Core{scriptName=name,commands=new ArrayList{new Command(291),new Command(5),new Command(292)},currentCommandIndex=2});}
  for(int n=0;n<32;n++){var core=cores[n%4];string raw="Value: "+n;Need(CW3Runtime.CaptureCrpl(raw,core)==raw,"raw model retained");Need(CW3Runtime.ForGuiMessage(raw)=="值："+n,"alternating script numeric display");}
  var first=cores[0];GameSpace.instance.scriptManager.Scripts[first.scriptName]+=" edited";CW3Runtime.CaptureCrpl("Value: 7",first);Need(CW3Runtime.ForGuiMessage("Value: 7")=="Value: 7","source drift falls back");GameSpace.instance.scriptManager.Scripts[first.scriptName]="owned script 0";
  first.commands=new ArrayList{new Command(291),new Command(292),new Command(292)};CW3Runtime.CaptureCrpl("Value: 7",first);Need(CW3Runtime.ForGuiMessage("Value: 7")=="Value: 7","replacement ordinal drift falls back");first.commands=new ArrayList{new Command(291),new Command(5),new Command(292)};CW3Runtime.CaptureCrpl("Value: 9",first);Need(CW3Runtime.ForGuiMessage("Value: 9")=="值：9","replacement restores correct binding");
  CW3Runtime.ClearScriptContexts();CW3Runtime.CaptureCrpl("Value: 11",first);Need(CW3Runtime.ForGuiMessage("Value: 11")=="值：11","scene clear retains translation behavior");first.currentCommandIndex=99;CW3Runtime.CaptureCrpl("Value: 12",first);Need(CW3Runtime.ForGuiMessage("Value: 12")=="Value: 12","invalid command does not reuse earlier GUI binding");
  first.currentCommandIndex=2;CW3Runtime.CaptureCrpl("Value: 13",first);var cache=(ScriptContextCache)Get("scriptContexts");Need(cache.RetainedOrdinals>0,"runtime cache populated");var pump=new CW3RuntimePump();typeof(CW3RuntimePump).GetMethod("OnLevelWasLoaded",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(pump,new object[]{3});Need(cache.RetainedOrdinals==0,"actual scene callback clears caches");CW3Runtime.CaptureCrpl("Value: 14",first);Need(CW3Runtime.ForGuiMessage("Value: 14")=="值：14","scene callback preserves subsequent translation");typeof(CW3RuntimePump).GetMethod("OnDestroy",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(pump,null);Need(cache.RetainedOrdinals==0,"pump destruction releases caches");
  Console.WriteLine("PASS "+checks+" shipped runtime script-context checks");
 }
